// Findings report, generated by the pipeline (retail/report.py).

import { load } from '../data.js';
import { escape, number, compactPounds } from '../format.js';

export async function render(container) {
  const [report, meta] = await Promise.all([load('report'), load('meta')]);
  const audit = meta.audit;
  container.innerHTML = `
    <div class="card" style="margin-bottom:16px">
      <p>A UK online gift wholesaler selling mostly to trade customers, ${audit.first_timestamp.slice(0, 10)} to ${audit.last_timestamp.slice(0, 10)}:
      ${number(audit.source_rows)} transaction lines, ${number(audit.orders)} orders, ${compactPounds(audit.sales_gbp)} of merchandise sales.
      Every figure below is written by the pipeline from the same data as the charts. The same report is in
      <a href="https://github.com/altz211/data-science/blob/main/retail-intelligence/docs/report.md">docs/report.md</a>.</p>
    </div>
    <div class="findings">${report.sections.map((s, i) => `
      <article class="card finding">
        <div class="metric">${escape(s.metric)}<small>${escape(s.metric_label)}</small></div>
        <div><h2>${i + 1}. ${escape(s.title)}</h2><p>${escape(s.finding)}</p><p class="action"><b>What to do:</b> ${escape(s.action)}</p></div>
      </article>`).join('')}
    </div>
    <div class="card" style="margin-top:16px"><h2>Caveats</h2><ul class="note">
      <li>Sales are gross merchandise sales in GBP. There is no cost, margin or stock data, so nothing here is profit.</li>
      <li>Customer analysis covers identified customers only; some sales have no customer ID.</li>
      <li>December 2009 includes customers who were active before the data starts, so that cohort is not truly new.</li>
      <li>Model results come from one retailer and one Christmas season. They show the method works, not a guaranteed uplift.</li>
    </ul></div>`;
}
